/// <summary>
/// The <c>METPurchReceiptsListDP_Extension</c> class is the report Data Provider class for the
/// <c>PurchReceiptsList</c> SSRS report.
/// </summary>
[ExtensionOf(classStr(PurchReceiptsListDP))]
final class METPurchReceiptsListDP_Extension
{
}

Method.Source:
/// <summary>
/// Inserts the purchase receipts list header.
/// </summary>
/// <param name = "_purchReceiptsListHeaderTmp">
/// A <c>PurchReceiptsListHeaderTmp</c> purchase receipts list header record to insert.
/// </param>
protected void insertPurchaseReceiptsListHeader(PurchReceiptsListHeaderTmp _purchReceiptsListHeaderTmp)
{
    if (_purchReceiptsListHeaderTmp.PurchId)
    {
        _purchReceiptsListHeaderTmp = PurchReceiptsListDP::getPODockCopyHeaderData(_purchReceiptsListHeaderTmp, _purchReceiptsListHeaderTmp.PurchId);           
    }

    next insertPurchaseReceiptsListHeader(_purchReceiptsListHeaderTmp);
}

/// <summary>
/// Inserts the purchase receipts list line.
/// </summary>
/// <param name = "_purchReceiptsListDetailsTmp">
/// A <c>PurchReceiptsListDetailsTmp</c> purchase receipts list line record to insert.
/// </param>
protected void insertPurchaseReceiptsListLine(PurchReceiptsListDetailsTmp _purchReceiptsListDetailsTmp)
{
    if (_purchReceiptsListDetailsTmp.JournalRecId)
    {
        _purchReceiptsListDetailsTmp = PurchReceiptsListDP::getPODockCopyLineData(_purchReceiptsListDetailsTmp, VendReceiptsListJour::findRecId(_purchReceiptsListDetailsTmp.JournalRecId).PurchId, _purchReceiptsListDetailsTmp.PurchaseLineLineNumber);
    }
    next insertPurchaseReceiptsListLine(_purchReceiptsListDetailsTmp);
}

/// <summary>
/// Insert PO Dock copy header details
/// </summary>
/// <param name = "_purchReceiptsListHeaderTmp">PurchReceiptsListHeaderTmp</param>
/// <param name = "_purchId">PurchId</param>
/// <returns>PurchReceiptsListHeaderTmp</returns>
protected static PurchReceiptsListHeaderTmp getPODockCopyHeaderData(PurchReceiptsListHeaderTmp _purchReceiptsListHeaderTmp, PurchId _purchId)
{
    PurchLine                       PurchLineQtySum;
    HcmWorker                       placerWorker;
    PurchTable                      purchTable      = purchTable::find(_purchId);
    METPurchTable                   metPurchTable   = METPurchTable::find(purchTable.PurchId);

    _purchReceiptsListHeaderTmp.METUnderBond              = metPurchTable.UnderBond;
    _purchReceiptsListHeaderTmp.METOrderNum               = purchTable.PurchId;
    _purchReceiptsListHeaderTmp.METVendAccount            = purchTable.OrderAccount;
    _purchReceiptsListHeaderTmp.METVendName               = purchTable.vendorName();
    _purchReceiptsListHeaderTmp.METVendAddress            = purchTable.vendorAddress();
    _purchReceiptsListHeaderTmp.METVendPhone              = purchTable.vendorPhone();
    _purchReceiptsListHeaderTmp.METABNNumber              = purchTable.vendTable_OrderAccount().VATNum;
    _purchReceiptsListHeaderTmp.METWarehouseName          = InventLocation::find(purchTable.InventLocationId).Name;
    _purchReceiptsListHeaderTmp.METWarehouseAddress       = InventLocation::find(purchTable.InventLocationId).address();
    _purchReceiptsListHeaderTmp.METWarehousePhone         = PurchReceiptsListDP::getPODeliveryAddressContactPhone(purchTable.InventLocationId);
    _purchReceiptsListHeaderTmp.METSpecialPOInstructions  = purchTable.ReqAttention;
    _purchReceiptsListHeaderTmp.METGenerateDateAndTime    = purchTable.CreatedDateTime;
    _purchReceiptsListHeaderTmp.METExpectDelvDate         = purchTable.DeliveryDate;
    _purchReceiptsListHeaderTmp.METAppointmentDateAndTime = metPurchTable.POYardDAppointmentStartDateTime;

    placerWorker = HcmWorker::find(purchTable.WorkerPurchPlacer);

    if(placerWorker)
    {
        _purchReceiptsListHeaderTmp.METContactName        = placerWorker.name();
        _purchReceiptsListHeaderTmp.METContactEmail       = placerWorker.email();
        _purchReceiptsListHeaderTmp.METContactPhone       = placerWorker.phone();
    }

    select sum(PurchQty) from PurchLineQtySum
        where PurchLineQtySum.PurchId == purchTable.PurchId;

    _purchReceiptsListHeaderTmp.METTotal                  = PurchLineQtySum.PurchQty;

    return _purchReceiptsListHeaderTmp;
}

/// <summary>
/// Insert PO Dock copy line details
/// </summary>
/// <param name = "_purchReceiptsListDetailsTmp">PurchReceiptsListHeaderTmp</param>
/// <param name = "_purchId">PurchId</param>
/// <param name = "_lineNumber">Line number</param>
/// <returns>PurchReceiptsListDetailsTmp</returns>
protected static PurchReceiptsListDetailsTmp getPODockCopyLineData(PurchReceiptsListDetailsTmp _purchReceiptsListDetailsTmp, PurchId _purchId, TradeLineNumber _lineNumber)
{
    PurchTable                  purchTable;
    PurchLine                   purchLine;
    InventDim                   metInventDimSlotArea;
    InventTable                 inventTable;
    METInventTable              metInventTable;
    InventDim                   inventDim;
    METInventItemOrderSetup     metInventItemOrderSetup;
    VendReceiptsListTrans       vendReceiptsListTrans;

    purchTable = PurchTable::find(_purchId);

    select firstonly purchLine
        where purchLine.PurchId == _purchId && !purchLine.IsDeleted && purchLine.LineNumber == _lineNumber
            join inventDim
                where inventDim.inventDimId == purchLine.InventDimId
            join inventTable
                where inventTable.ItemId == purchLine.ItemId
            outer join metInventTable
                where metInventTable.ItemId == inventTable.ItemId;

    if (purchLine)
    {
        select firstonly CartonPerLayer, Layers from metInventItemOrderSetup
            where metInventItemOrderSetup.ItemId == purchLine.ItemId
                && metInventItemOrderSetup.SiteId == purchTable.InventSiteId;    

        _purchReceiptsListDetailsTmp.METItemDecription      = inventTable.productName(SystemParameters::getSystemLanguageId());
        _purchReceiptsListDetailsTmp.METItemId              = purchLine.ItemId;
        _purchReceiptsListDetailsTmp.METLineNumber          = purchLine.LineNumber;
        _purchReceiptsListDetailsTmp.METUOM                 = purchLine.PurchUnit;
        _purchReceiptsListDetailsTmp.METItemSize            = metInventTable.ItemSize;
        _purchReceiptsListDetailsTmp.METBarCode             = purchLine.BarCode;

        metInventDimSlotArea.InventSiteId        = inventDim.InventSiteId;
        metInventDimSlotArea.InventLocationId    = inventDim.InventLocationId;

        metInventDimSlotArea = InventDim::findOrCreate(metInventDimSlotArea);

        _purchReceiptsListDetailsTmp.METSlotArea            = METReqItemTable::find(ReqItemTable::find(purchLine.ItemId, metInventDimSlotArea.inventDimId).RecId).SlotLoc1Area;
        _purchReceiptsListDetailsTmp.METQty                 = purchLine.PurchQty;
        _purchReceiptsListDetailsTmp.METIsCWItem            = inventTable.pdsCWItem();

        select firstonly InventQty from vendReceiptsListTrans
            where vendReceiptsListTrans.InventTransId == purchLine.InventTransId;

        _purchReceiptsListDetailsTmp.pdsCWQty               = vendReceiptsListTrans.InventQty;
        _purchReceiptsListDetailsTmp.METTi                  = metInventItemOrderSetup.CartonPerLayer;
        _purchReceiptsListDetailsTmp.METHi                  = metInventItemOrderSetup.Layers;              
    }

    return _purchReceiptsListDetailsTmp;
}

/// <summary>
/// get the phone number for receiving dock
/// </summary>
/// <param name = "_metLogisticsLocationRole">LogisticsLocationRole</param>
/// <returns>Phone</returns>
public static METWHPhone getPODeliveryAddressContactPhone(InventLocationId _InventLocationId)
{
    InventLocation                  	inventLocation;
    LogisticsEntityPostalAddressView    	postalAddressView;
    LogisticsElectronicAddress          	electronicAddress;
    LogisticsLocation                   	contactLocation;

    inventLocation = inventLocation::find(_InventLocationId);
    if (inventLocation)
    {
        select firstonly postalAddressView
        where   postalAddressView.Entity     == inventLocation.RecId
        &&      postalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        &&      postalAddressView.isPrimary  == NoYes::Yes;

        if (postalAddressView)
        {
            select firstOnly electronicAddress where electronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
            join contactLocation where contactLocation.ParentLocation  == postalAddressView.Location
                && contactLocation.RecId == electronicAddress.Location;

        }
    }
    return electronicAddress.Locator;

}
